  6	final class TopologicalSort {
  7	
  8	    private static final int SAMPLE_VERTEX_COUNT = 6;
  9	    private static final Edge[] SAMPLE_EDGES = {
 10	        new Edge(0, 1),
 11	        new Edge(1, 2),
 12	        new Edge(2, 3),
 13	        new Edge(4, 5),
 14	        new Edge(5, 1),
 15	        new Edge(5, 2)
 16	    };
 17	
 18	    private TopologicalSort() {
 19	    }
 20	
 21	    private static final class Edge {
 22	        private final int from;
 23	        private final int to;
 24	
 25	        private Edge(int from, int to) {
 26	            this.from = from;
 27	            this.to = to;
 28	        }
 29	    }
 30	
 31	    static List<Integer> topoSort(List<? extends List<Integer>> adjacencyList) {
 32	        return topologicalSort(adjacencyList);
 33	    }
 34	
 35	    static List<Integer> topologicalSort(List<? extends List<Integer>> adjacencyList) {
 36	        int vertexCount = adjacencyList.size();
 37	        int[] inDegree = calculateInDegrees(adjacencyList);
 38	        Deque<Integer> readyVertices = collectZeroInDegreeVertices(inDegree);
 39	        List<Integer> sortedVertices = new ArrayList<>(vertexCount);
 40	
 41	        while (!readyVertices.isEmpty()) {
 42	            int vertex = readyVertices.removeFirst();
 43	            sortedVertices.add(vertex);
 44	            enqueueReadyNeighbors(adjacencyList.get(vertex), inDegree, readyVertices);
 45	        }
 46	
 47	        return sortedVertices;
 48	    }
 49	
 50	    static void addEdge(List<? extends List<Integer>> adjacencyList, int from, int to) {
 51	        adjacencyList.get(from).add(to);
 52	    }
 53	
 54	    private static List<List<Integer>> buildGraph(int vertexCount, Edge[] edges) {
 55	        List<List<Integer>> adjacencyList = createEmptyAdjacencyList(vertexCount);
 56	        for (Edge edge : edges) {
 57	            addEdge(adjacencyList, edge.from, edge.to);
 58	        }
 59	        return adjacencyList;
 60	    }
 61	
 62	    private static int[] calculateInDegrees(List<? extends List<Integer>> adjacencyList) {
 63	        int[] inDegree = new int[adjacencyList.size()];
 64	        for (List<Integer> neighbors : adjacencyList) {
 65	            for (int next : neighbors) {
 66	                inDegree[next]++;
 67	            }
 68	        }
 69	        return inDegree;
 70	    }
 71	
 72	    private static Deque<Integer> collectZeroInDegreeVertices(int[] inDegree) {
 73	        Deque<Integer> readyVertices = new ArrayDeque<>();
 74	        for (int vertex = 0; vertex < inDegree.length; vertex++) {
 75	            if (inDegree[vertex] == 0) {
 76	                readyVertices.addLast(vertex);
 77	            }
 78	        }
 79	        return readyVertices;
 80	    }
 81	
 82	    private static void enqueueReadyNeighbors(
 83	            List<Integer> neighbors,
 84	            int[] inDegree,
 85	            Deque<Integer> readyVertices
 86	    ) {
 87	        for (int next : neighbors) {
 88	            inDegree[next]--;
 89	            if (inDegree[next] == 0) {
 90	                readyVertices.addLast(next);
 91	            }
 92	        }
 93	    }
 94	
 95	    private static List<List<Integer>> createEmptyAdjacencyList(int vertexCount) {
 96	        List<List<Integer>> adjacencyList = new ArrayList<>(vertexCount);
 97	        for (int vertex = 0; vertex < vertexCount; vertex++) {
 98	            adjacencyList.add(new ArrayList<>());
 99	        }
100	        return adjacencyList;
101	    }
102	
103	    private static void printVertices(List<Integer> vertices) {
104	        System.out.println(formatVertices(vertices));
105	    }
106	
107	    private static String formatVertices(List<Integer> vertices) {
108	        StringBuilder output = new StringBuilder();
109	        for (int vertex : vertices) {
110	            output.append(vertex).append(' ');
111	        }
112	        return output.toString();
113	    }
114	
115	    public static void main(String[] args) {
116	        List<List<Integer>> adjacencyList = buildGraph(SAMPLE_VERTEX_COUNT, SAMPLE_EDGES);
117	        List<Integer> sortedVertices = topologicalSort(adjacencyList);
118	        printVertices(sortedVertices);
119	    }
120	}

